-- 0008_entities.sql
-- Entitas per perusahaan (sumber kebenaran tab, tabel PA, prefix nomor PA, dan pillar vendor) + tabel PA entitas baru.
-- Sinar Mas Tjipta (SMT): AGRI, APP, LAND, EFIN, SMT. Eka Tjipta Foundation (ETF): AGRI, APP, LAND, EFIN, SETF, ETF.
-- Placeholder {{schema}} diganti apply_migrations.py. Idempotent: aman dijalankan ulang.
-- Badan fungsi ditulis sebagai literal '...' supaya split_script memecah file ini dengan benar.

create table if not exists {{schema}}.entities (
    "id" bigint generated by default as identity primary key,
    "company_id" bigint not null,
    "code" text collate "C" not null,
    "label" text collate "C" not null,
    "tab_key" text collate "C" not null,
    "pa_table" text collate "C" not null,
    "lines_table" text collate "C" not null,
    "pa_prefix" text collate "C" not null,
    "pillar" text collate "C" not null,
    "urutan" integer not null default 0,
    "aktif" boolean not null default true,
    unique ("company_id", "code"),
    unique ("company_id", "tab_key")
);
alter table {{schema}}.entities enable row level security;

-- Tabel PA entitas baru = kloning struktur tabel PA yang ada (kolom sama, termasuk kolom PR Portal dan serah terima).
create table if not exists {{schema}}.sm_pa (like {{schema}}.etf_pa including all);
create table if not exists {{schema}}.sm_pa_lines (like {{schema}}.etf_pa_lines including all);
create table if not exists {{schema}}.ef_pa (like {{schema}}.etf_pa including all);
create table if not exists {{schema}}.ef_pa_lines (like {{schema}}.etf_pa_lines including all);
alter table {{schema}}.sm_pa enable row level security;
alter table {{schema}}.sm_pa_lines enable row level security;
alter table {{schema}}.ef_pa enable row level security;
alter table {{schema}}.ef_pa_lines enable row level security;

-- Seed (tidak menimpa perubahan manual): kode perusahaan, kode entitas, label, tab, tabel PA, prefix, pillar, urutan.
insert into {{schema}}.entities (company_id, code, label, tab_key, pa_table, lines_table, pa_prefix, pillar, urutan)
select c.id, v.code, v.label, v.tab_key, v.pa_table, v.pa_table || '_lines', v.pa_prefix, v.pillar, v.urutan
  from {{schema}}.companies c
  join (values
        ('SMT', 'AGRI', 'AGRI', 'agri',   'etf_pa',    'SMT',  'AGRI', 1),
        ('SMT', 'APP',  'APP',  'app',    'app_pa',    'APP',  'APP',  2),
        ('SMT', 'LAND', 'LAND', 'sml',    'sml_pa',    'LAND', 'LAND', 3),
        ('SMT', 'EFIN', 'EFIN', 'energy', 'energy_pa', 'EFIN', 'EFIN', 4),
        ('SMT', 'SMT',  'SMT',  'sm',     'sm_pa',     'SM',   'SMT',  5),
        ('ETF', 'AGRI', 'AGRI', 'agri',   'etf_pa',    'ETF',  'AGRI', 1),
        ('ETF', 'APP',  'APP',  'app',    'app_pa',    'APP',  'APP',  2),
        ('ETF', 'LAND', 'LAND', 'sml',    'sml_pa',    'LAND', 'LAND', 3),
        ('ETF', 'EFIN', 'EFIN', 'energy', 'energy_pa', 'EFIN', 'EFIN', 4),
        ('ETF', 'SETF', 'SETF', 'setf',   'setf_pa',   'SETF', 'SETF', 5),
        ('ETF', 'ETF',  'ETF',  'ef',     'ef_pa',     'EF',   'ETF',  6)
       ) as v (company, code, label, tab_key, pa_table, pa_prefix, pillar, urutan)
    on v.company = c.code
on conflict (company_id, code) do nothing;

-- Prefix nomor PA untuk (perusahaan, tab); null bila tab bukan milik perusahaan itu.
create or replace function {{schema}}.fn_prp_entity_prefix(p_company_id bigint, p_tab_key text)
returns text
language sql
stable
set search_path = {{schema}}
as '
    select e.pa_prefix from entities e where e.company_id = p_company_id and e.tab_key = p_tab_key and e.aktif limit 1
';

-- Perusahaan dari awalan cost center: PO -> SMT, TF -> ETF; selain itu null.
create or replace function {{schema}}.fn_prp_company_of_cost_center(p_cost_center text)
returns bigint
language sql
stable
set search_path = {{schema}}
as '
    select c.id from companies c
     where c.code = case
        when upper(trim(coalesce(p_cost_center, ''''))) like ''PO%'' then ''SMT''
        when upper(trim(coalesce(p_cost_center, ''''))) like ''TF%'' then ''ETF''
     end
';

-- Fungsi fn_prp_* internal tidak boleh dipanggil siapa pun selain owner (pola akhir 0006): cabut EXECUTE PUBLIC/anon/authenticated.
do '
declare
    f record;
    r text;
begin
    for f in select p.proname, pg_get_function_identity_arguments(p.oid) as args
               from pg_proc p join pg_namespace n on n.oid = p.pronamespace
              where n.nspname = ''{{schema}}'' and p.proname like ''fn\_prp\_%''
    loop
        execute format(''revoke all on function %I.%I(%s) from public'', ''{{schema}}'', f.proname, f.args);
        foreach r in array array[''anon'', ''authenticated''] loop
            if exists (select 1 from pg_roles where rolname = r) then
                execute format(''revoke all on function %I.%I(%s) from %I'', ''{{schema}}'', f.proname, f.args, r);
            end if;
        end loop;
    end loop;
end
';

notify pgrst, 'reload schema';
